import os, requests
os.chdir('/home/data4/xiangyu/BioDSA/workdir')
queries=['"air leak test" hepatectomy organ space infection','air leak test major hepatectomy surgical site infection','hepatectomy "organ-space infection" air leak']
for q in queries:
    u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
    r=requests.get(u,params={'db':'pubmed','term':q,'retmode':'json','retmax':10},timeout=20)
    print('\nQUERY:',q,'STATUS:',r.status_code)
    try:
        ids=r.json()['esearchresult']['idlist']
        print('PMIDS:',ids)
        if ids:
            s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
            for i in ids: print(i,s[i].get('title'),s[i].get('pubdate'))
    except Exception as e: print('ERROR',str(e),r.text[:300])
